@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private Shipment? searchedShipment;
    private string? trackError;

    private async Task TrackShipment()
    {
        searchedShipment = null;
        trackError = null;

        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            trackError = "Please enter a tracking number.";
            return;
        }

        searchedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        if (searchedShipment is null)
        {
            trackError = "No shipment found with that tracking number.";
        }
    }

    private async Task HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }
}
