@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container mt-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipments in real-time from anywhere in the world.</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Track a Shipment</h5>
                    <p class="card-text">Enter your tracking number to check the current status and estimated delivery.</p>
                    <div class="input-group">
                        <input type="text" class="form-control" placeholder="e.g. SHP-20260706-A1B2C3D4"
                               @bind="trackingInput" @bind:event="oninput"
                               @onkeydown="HandleTrackKeyDown" />
                        <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
                    </div>
                    @if (searchedShipment is not null)
                    {
                        <div class="alert alert-success mt-3">
                            <strong>@searchedShipment.TrackingNumber</strong><br />
                            Status: <span class="badge bg-info">@searchedShipment.Status</span><br />
                            Destination: @searchedShipment.Destination<br />
                            @if (searchedShipment.EstimatedDelivery.HasValue)
                            {
                                <span>Estimated Delivery: @searchedShipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</span>
                            }
                        </div>
                    }
                    @if (trackError is not null)
                    {
                        <div class="alert alert-warning mt-3">@trackError</div>
                    }
                </div>
            </div>
        </div>

        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Dispatcher Portal</h5>
                    <p class="card-text">Manage shipments, update statuses, and create new shipments.</p>
                    <AuthorizeView>
                        <Authorized>
                            <a href="dispatch" class="btn btn-outline-primary">Go to Dispatch Dashboard</a>
                        </Authorized>
                        <NotAuthorized>
                            <a href="Account/Login" class="btn btn-outline-secondary">Login to access</a>
                        </NotAuthorized>
                    </AuthorizeView>
                </div>
            </div>
        </div>
    </div>

    <AuthorizeView>
        <Authorized>
            <div class="row mt-4">
                <div class="col-12">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">My Shipments</h5>
                            <a href="my-shipments" class="btn btn-outline-primary">View My Shipments</a>
                        </div>
                    </div>
                </div>
            </div>
        </Authorized>
    </AuthorizeView>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private Shipment? searchedShipment;
    private string? trackError;

    private async Task TrackShipment()
    {
        searchedShipment = null;
        trackError = null;

        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            trackError = "Please enter a tracking number.";
            return;
        }

        searchedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        if (searchedShipment is null)
        {
            trackError = "No shipment found with that tracking number.";
        }
    }

    private async Task HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }
}

