@attribute [Authorize]

<PageTitle>Dispatch Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>Dispatch Dashboard</h2>
        <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
            @(showCreateForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5>Create New Shipment</h5>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label">Origin</label>
                        <input type="text" class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Destination</label>
                        <input type="text" class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Estimated Delivery</label>
                        <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-12">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="col-12">
                        <button class="btn btn-primary" @onclick="CreateShipment">Create Shipment</button>
                    </div>
                </div>
            </div>
        </div>
    }

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination or tracking number..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (!FilteredShipments.Any())
    {
        <p>No shipments found.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Customer</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in FilteredShipments)
                    {
                        <tr>
                            <td><code>@shipment.TrackingNumber</code></td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                            <td>@shipment.CustomerEmail</td>
                            <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        value="@((int)shipment.Status)"
                                        @onchange="e => UpdateStatus(shipment, e)">
                                    @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@((int)status)">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment>? shipments;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private bool showCreateForm;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => shipments?
        .Where(s => string.IsNullOrWhiteSpace(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
            || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@attribute [Authorize]

<PageTitle>My Shipments</PageTitle>

<div class="container mt-4">
    <h2>My Shipments</h2>
    <p>Viewing shipments associated with your account.</p>

    @if (shipments is null)
    {
        <p><em>Loading...</em></p>
    }
    else if (!shipments.Any())
    {
        <p>You have no shipments yet.</p>
    }
    else
    {
        <div class="row">
            @foreach (var shipment in shipments)
            {
                <div class="col-md-6 col-lg-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h6 class="card-title"><code>@shipment.TrackingNumber</code></h6>
                            <p class="card-text mb-1">
                                <strong>Status:</strong>
                                <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                            </p>
                            <p class="card-text mb-1"><strong>From:</strong> @shipment.Origin</p>
                            <p class="card-text mb-1"><strong>To:</strong> @shipment.Destination</p>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <p class="card-text mb-1">
                                    <strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                                </p>
                            }
                            @if (!string.IsNullOrWhiteSpace(shipment.Description))
                            {
                                <p class="card-text text-muted">@shipment.Description</p>
                            }
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [CascadingParameter] private Task<AuthenticationState> AuthStateTask { get; set; } = default!;

    private List<Shipment>? shipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateTask;
        var email = authState.User.Identity?.Name ?? string.Empty;
        shipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

